  ui_story_5025_50253301_208_dialog_content = "Certo...",
  ui_story_5025_50253301_209_dialog_content = "\"Você pode agradecer PlayerName\"... Feito.",
  ui_story_5025_50253301_210_dialog_content = "eu quero agradecer PlayerName... e todos os outros.",
  ui_story_5025_50253301_211_dialog_content = "Jamais esquecerei nossa viagem ao mar.",
  ui_story_5025_50253301_212_dialog_content = "E... acabei de receber Palomaresposta de. Ela foi muito rápida dessa vez.",
