  ui_story_5025_50253301_214_dialog_content = "\"Mas se for para o Navigator, eu faço.\"",
  ui_story_5025_50253301_215_dialog_content = "\"Ele é um cara muito legal. Por favor, deixe essa mensagem para mim.\"",
