  ui_story_5025_50253301_236_dialog_content = "Sim... Acho que preciso de um caderno maior da próxima vez.",
  ui_story_5025_50253301_237_dialog_content = "Você salvou PlayerName uma linha?",
  ui_story_5025_50253301_238_dialog_content = "É claro. As últimas palavras devem vir de PlayerName. E você ainda não escreveu nada.",
  ui_story_5025_50253301_239_dialog_content = "Eu? Ahem... Estamos juntos há tanto tempo. Isso realmente não é necessário...",
